SELECT kc.name AS constraint_name, i.type_desc, col.name AS column_name, ic.is_descending_key FROM sys.key_constraints kc JOIN sys.indexes i ON i.object_id = kc.parent_object_id AND i.index_id = kc.unique_index_id JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id JOIN sys.columns col ON col.object_id = ic.object_id AND col.column_id = ic.column_id WHERE kc.parent_object_id = OBJECT_ID(N'odd schema.My]Table') AND kc.type = 'PK' ORDER BY ic.key_ordinal